1	import { describe, it, expect, beforeEach, vi } from "vitest";
2	import { createTestDb, seedBaseData } from "~/test/setup";
3	import * as schema from "~/db/schema";
4	
5	let testDb: ReturnType<typeof createTestDb>;
6	let base: ReturnType<typeof seedBaseData>;
7	
8	vi.mock("~/db", () => ({
9	  get db() {
10	    return testDb;
11	  },
12	}));
13	
14	// Import after mock so the module picks up our test db
15	import {
16	  getLessonProgress,
17	  getLessonProgressForCourse,
18	  markLessonComplete,
19	  markLessonInProgress,
20	  resetLessonProgress,
21	  calculateProgress,
22	  getCompletedLessonCount,
23	  getTotalLessonCount,
24	  isLessonCompleted,
25	  getNextIncompleteLesson,
26	} from "./progressService";
27	
28	// Helper to create a module with lessons in the test db
29	function createModuleWithLessons(
30	  courseId: number,
31	  moduleTitle: string,
32	  position: number,
33	  lessonCount: number,
34	  durationMinutes?: number
35	) {
36	  const mod = testDb
37	    .insert(schema.modules)
38	    .values({
39	      courseId,
40	      title: moduleTitle,
41	      position,
42	    })
43	    .returning()
44	    .get();
45	
46	  const createdLessons = [];
47	  for (let i = 0; i < lessonCount; i++) {
48	    const lesson = testDb
49	      .insert(schema.lessons)
50	      .values({
51	        moduleId: mod.id,
52	        title: `Lesson ${i + 1}`,
53	        position: i + 1,
54	        durationMinutes: durationMinutes ?? null,
55	      })
56	      .returning()
57	      .get();
58	    createdLessons.push(lesson);
59	  }
60	
61	  return { module: mod, lessons: createdLessons };
62	}
63	
64	describe("progressService", () => {
65	  beforeEach(() => {
66	    testDb = createTestDb();
67	    base = seedBaseData(testDb);
68	  });
69	
70	  describe("markLessonComplete", () => {
71	    it("marks a lesson as completed with a new progress record", () => {
72	      const { lessons } = createModuleWithLessons(base.course.id, "Module 1", 1, 1);
73	
74	      const progress = markLessonComplete(base.user.id, lessons[0].id);
75	
76	      expect(progress).toBeDefined();
77	      expect(progress.userId).toBe(base.user.id);
78	      expect(progress.lessonId).toBe(lessons[0].id);
79	      expect(progress.status).toBe(schema.LessonProgressStatus.Completed);
80	      expect(progress.completedAt).toBeDefined();
81	      expect(progress.completedAt).not.toBeNull();
82	    });
83	
84	    it("updates an existing in-progress record to completed", () => {
85	      const { lessons } = createModuleWithLessons(base.course.id, "Module 1", 1, 1);
86	
87	      markLessonInProgress(base.user.id, lessons[0].id);
88	      const progress = markLessonComplete(base.user.id, lessons[0].id);
89	
90	      expect(progress.status).toBe(schema.LessonProgressStatus.Completed);
91	      expect(progress.completedAt).not.toBeNull();
92	    });
93	
94	    it("is idempotent — completing an already completed lesson still returns completed", () => {
95	      const { lessons } = createModuleWithLessons(base.course.id, "Module 1", 1, 1);
96	
97	      markLessonComplete(base.user.id, lessons[0].id);
98	      const progress = markLessonComplete(base.user.id, lessons[0].id);
99	
100	      expect(progress.status).toBe(schema.LessonProgressStatus.Completed);
101	    });
102	  });
103	
104	  describe("markLessonInProgress", () => {
105	    it("marks a lesson as in-progress with a new progress record", () => {
106	      const { lessons } = createModuleWithLessons(base.course.id, "Module 1", 1, 1);
107	
108	      const progress = markLessonInProgress(base.user.id, lessons[0].id);
109	
110	      expect(progress.status).toBe(schema.LessonProgressStatus.InProgress);
111	      expect(progress.completedAt).toBeNull();
112	    });
113	
114	    it("does not downgrade a completed lesson back to in-progress", () => {
115	      const { lessons } = createModuleWithLessons(base.course.id, "Module 1", 1, 1);
116	
117	      markLessonComplete(base.user.id, lessons[0].id);
118	      const progress = markLessonInProgress(base.user.id, lessons[0].id);
119	
120	      expect(progress.status).toBe(schema.LessonProgressStatus.Completed);
121	    });
122	
123	    it("updates an existing not-started record to in-progress", () => {
124	      const { lessons } = createModuleWithLessons(base.course.id, "Module 1", 1, 1);
125	
126	      // Create initial in-progress, then mark in-progress again (no-op for in_progress)
127	      const first = markLessonInProgress(base.user.id, lessons[0].id);
128	      const second = markLessonInProgress(base.user.id, lessons[0].id);
129	
130	      expect(second.status).toBe(schema.LessonProgressStatus.InProgress);
131	      expect(second.id).toBe(first.id);
132	    });
133	  });
134	
135	  describe("getLessonProgress", () => {
136	    it("returns the progress record for a user/lesson pair", () => {
137	      const { lessons } = createModuleWithLessons(base.course.id, "Module 1", 1, 1);
138	
139	      markLessonComplete(base.user.id, lessons[0].id);
140	
141	      const progress = getLessonProgress(base.user.id, lessons[0].id);
142	      expect(progress).toBeDefined();
143	      expect(progress!.status).toBe(schema.LessonProgressStatus.Completed);
144	    });
145	
146	    it("returns undefined when no progress exists", () => {
147	      const { lessons } = createModuleWithLessons(base.course.id, "Module 1", 1, 1);
148	
149	      const progress = getLessonProgress(base.user.id, lessons[0].id);
150	      expect(progress).toBeUndefined();
151	    });
152	  });
153	
154	  describe("getLessonProgressForCourse", () => {
155	    it("returns all lesson progress records for a user in a course", () => {
